"""The frozen rule baselines (generated by scripts/build_mltaskbench_bundle.py; do not edit).

Source segments copied unchanged from scripts/build_candidate_pool.py (AutoGluon replica, type_of_target) and
scripts/run_rules.py (heuristic set, heuristic set + names), frozen 2026-09-26.
"""
import re

import numpy as np
import pandas as pd
from pandas.api.types import is_bool_dtype, is_float_dtype, is_integer_dtype, is_numeric_dtype
from sklearn.utils.multiclass import type_of_target


# ---- from scripts/build_candidate_pool.py
AG_MULTICLASS_UPPER_LIMIT = 1000
AG_LARGE_DATA_THRESHOLD = 1000
AG_REGRESS_THRESHOLD_LARGE = 0.05
AG_REGRESS_THRESHOLD_SMALL = 0.1

def rule_autogluon(y: pd.Series) -> str:
    """Replica of autogluon.core.utils.utils.infer_problem_type (same commit)."""
    y = y.replace([np.inf, -np.inf], np.nan).dropna()
    n = len(y)
    if n == 0:
        return "error"
    k = y.nunique()
    thr = AG_REGRESS_THRESHOLD_LARGE if n > AG_LARGE_DATA_THRESHOLD else AG_REGRESS_THRESHOLD_SMALL
    if k == 2:
        return "binary"
    # pandas 3 names its default string dtype "str"; AutoGluon's list predates it.
    if y.dtype.name in ("object", "category", "string", "str", "bool") or not is_numeric_dtype(y):
        return "multiclass"
    few = (k / n <= thr) and (k <= AG_MULTICLASS_UPPER_LIMIT)
    if is_float_dtype(y):
        return "multiclass" if few and np.array_equal(y, y.astype(int)) else "regression"
    if is_integer_dtype(y):
        return "multiclass" if few else "regression"
    return "error"

def rule_sklearn(y: pd.Series) -> str:
    try:
        return type_of_target(y.dropna().to_numpy())
    except Exception as ex:  # e.g. mixed types
        return f"error:{type(ex).__name__}"

# ---- from scripts/run_rules.py
B, M, O, CNT, CONT = "BINARY", "MULTICLASS", "ORDINAL", "COUNT_REGRESSION", "CONTINUOUS_REGRESSION"
AG_MAP = {"binary": B, "multiclass": M, "regression": CONT}
SK_MAP = {"binary": B, "multiclass": M, "continuous": CONT}
FEW_LEVELS = 10
MID_LEVELS = 30
KEYWORDS = {
    CNT: {"count", "counts", "number", "num", "rings", "flares", "frequency", "freq", "visits",
          "sessions", "times", "cases", "events", "calls"},
    O: {"quality", "grade", "score", "rating", "rank", "level", "severity", "stage", "satisfaction",
        "utility", "g3"},
    M: {"class", "type", "category", "species", "label", "kind", "method", "genre", "group"},
    CONT: {"price", "cost", "amount", "value", "weight", "area", "strength", "load", "temperature",
           "income", "wage", "salary", "fat", "medv", "lc50", "duration", "usage", "volume"},
}

def as_numeric(y):
    if is_numeric_dtype(y):
        return y.astype(float)
    v = pd.to_numeric(y, errors="coerce")
    return v.astype(float) if v.notna().all() else None

def profile(y):
    y = y.dropna()
    num = as_numeric(y)
    p = {"k": int(y.nunique()), "numeric": num is not None}
    if num is not None:
        p.update(integer=bool(np.all(np.mod(num, 1) == 0)), min=float(num.min()),
                 zero_is_mode=bool(num.mode().iloc[0] == 0) if len(num) else False)
    return p

def heuristic_set(y):
    p = profile(y)
    if p["k"] == 2:
        return {B}, B
    if not p["numeric"]:
        return {M}, M
    if not p["integer"]:
        return {CONT}, CONT
    nonneg, countlike = p["min"] >= 0, p["min"] == 0 and p["zero_is_mode"]
    if p["k"] <= FEW_LEVELS:
        s = {M, O} | ({CNT} if nonneg else set())
        return s, CNT if countlike else O
    if p["k"] <= MID_LEVELS:
        s = {O, CONT} | ({CNT} if nonneg else set())
        return s, CNT if countlike else O
    s = {CONT} | ({CNT} if nonneg else set())
    return s, CNT if countlike else CONT

def compatible(task, p):
    k = p["k"]
    if task == B:
        return k == 2
    if task in (M, O):
        return k > 2 and (not p["numeric"] or k <= (100 if task == M else MID_LEVELS))
    if task == CNT:
        return p["numeric"] and p.get("integer") and p["min"] >= 0
    return p["numeric"]

def tokens(name):
    name = re.sub(r"([a-z])([A-Z])", r"\1 \2", str(name))
    return {t for t in re.split(r"[^a-z0-9]+", name.lower()) if t}

def heuristic_names(y, target_name):
    s, ml = heuristic_set(y)
    p = profile(y)
    hits = [t for t, words in KEYWORDS.items() if tokens(target_name) & words]
    hits = [t for t in hits if compatible(t, p)]
    if len(hits) == 1:
        return s | {hits[0]}, hits[0]
    return s, ml
